WITH gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) + INTERVAL 45 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM device_readings), sessions_device_readings AS (SELECT id, device_code, reading_ts, temp_c, humidity, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT id, reading_ts, temp_c, humidity, session_id FROM sessions_device_readings ORDER BY humidity DESC, id ASC LIMIT 10
